import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.ClgMjOt7.js";const _=JSON.parse('{"title":"ログインと認証","description":"Web ログイン、リフレッシュトークンログイン、および複数アカウント管理","frontmatter":{"title":"ログインと認証","description":"Web ログイン、リフレッシュトークンログイン、および複数アカウント管理"},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md","lastUpdated":1786166106000}'),r={name:"guide/authentication.md"};function l(n,e,c,d,s,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ログインと認証" tabindex="-1">ログインと認証 <a class="header-anchor" href="#ログインと認証" aria-label="Permalink to &quot;ログインと認証&quot;">​</a></h1><p>Palleria では Pixiv API の利用にあたり OAuth2 認証を用います。アカウント情報は暗号化され端末内（Android KeyStore / Room DB）に保存されます。</p><hr><h2 id="ログイン方式" tabindex="-1">ログイン方式 <a class="header-anchor" href="#ログイン方式" aria-label="Permalink to &quot;ログイン方式&quot;">​</a></h2><h3 id="_1-web-ログイン-推奨" tabindex="-1">1. Web ログイン (推奨) <a class="header-anchor" href="#_1-web-ログイン-推奨" aria-label="Permalink to &quot;1. Web ログイン (推奨)&quot;">​</a></h3><p>アプリ内ブラウザ（Chrome Custom Tabs または WebView）で Pixiv の公式 OAuth ログインページを表示して認証します。</p><ol><li>ログイン画面で「Web ログイン」をタップします。</li><li>Pixiv のログイン画面が表示されるので、ID/パスワードまたは各サードパーティ連携（Google / Apple / Twitter）でログインします。</li><li>ログイン完了後、スキーム <code>pixiv://</code> によるリダイレクトが発生し、取得された <code>access_token</code> および <code>refresh_token</code> が保存されます。</li></ol><hr><h2 id="_2-リフレッシュトークンログイン" tabindex="-1">2. リフレッシュトークンログイン <a class="header-anchor" href="#_2-リフレッシュトークンログイン" aria-label="Permalink to &quot;2. リフレッシュトークンログイン&quot;">​</a></h2><p>すでに取得済みの <code>refresh_token</code>（文字列）を直接入力して認証を行う方法です。</p><ol><li>ログイン画面で「リフレッシュトークンでログイン」を選択します。</li><li><code>refresh_token</code> を入力し「ログイン」をタップすると、Rust API クライアント経由でトークンの有効性が検証されます。</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>refresh_token</code> はアカウント操作が可能な機密データです。外部への漏洩にご注意ください。</p></div><hr><h2 id="複数アカウント管理" tabindex="-1">複数アカウント管理 <a class="header-anchor" href="#複数アカウント管理" aria-label="Permalink to &quot;複数アカウント管理&quot;">​</a></h2><p>Palleria は複数アカウントの保持と切り替えに対応しています。</p><ul><li><strong>アカウント切り替えシート</strong>: アプリ内から保存済みアカウントの一覧を呼び出し、再ログインなしで即座にアクティブアカウントを変更できます。</li><li><strong>データ管理</strong>: アカウントごとに <code>AccountEntity</code> テーブルで管理され、設定画面から個別のログアウトやトークン破棄が可能です。</li></ul>',16)])])}const p=a(r,[["render",l]]);export{_ as __pageData,p as default};
